        private void RefreshLangPackButtons()
        {
            if (LangPacksPanel == null) return;
            LangPacksPanel.Children.Clear();

            var packs = LanguageService.GetAvailablePacks();

            var toggle = new System.Windows.Controls.Primitives.ToggleButton
            {
                MinWidth = 160,
                FontSize = Ui.FontM,
                Style = (System.Windows.Style)Application.Current.Resources["DropdownToggleStyle"],
            };

            var popupPanel = new StackPanel { Margin = new Thickness(4) };
            var popupBorder = new Border
            {
                BorderThickness = new Thickness(1),
                CornerRadius    = (CornerRadius)Application.Current.Resources["RadiusControl"],
                MinWidth        = 160,
                Margin          = new Thickness(0, 4, 0, 0),
                Effect          = (System.Windows.Media.Effects.Effect)Application.Current.Resources["CardShadow"],
                Child           = popupPanel,
            };
            // DynamicResource, not a direct snapshot — otherwise the popup background keeps the theme colours from construction
            // time if the user changes the theme while the popup exists (rare, but free to avoid with SetResourceReference).
            popupBorder.SetResourceReference(Border.BackgroundProperty, "BgCardBrush");
            popupBorder.SetResourceReference(Border.BorderBrushProperty, "CardBorderBrush");

            var popup = new System.Windows.Controls.Primitives.Popup
            {
                PlacementTarget = toggle,
                Placement       = System.Windows.Controls.Primitives.PlacementMode.Bottom,
                StaysOpen       = false,
                AllowsTransparency = true,
                PopupAnimation  = System.Windows.Controls.Primitives.PopupAnimation.Slide,
                Child           = popupBorder,
            };
            toggle.Checked   += (_, _) => popup.IsOpen = true;
            toggle.Unchecked += (_, _) => popup.IsOpen = false;
            // StaysOpen="False" closes the Popup by itself on a click outside — sync the ToggleButton back to Unchecked,
            // otherwise it would stay visually "pressed".
            popup.Closed     += (_, _) => toggle.IsChecked = false;

            int selectedIdx = 0;
            int i = 0;
            foreach (var (code, name, _) in packs)
            {
                var itemBtn = new Button
                {
                    Content = name,
                    Tag     = code,
                    Style   = (System.Windows.Style)Application.Current.Resources["DropdownItemStyle"],
                    HorizontalAlignment = System.Windows.HorizontalAlignment.Stretch,
                };
                itemBtn.Click += (s, e) =>
                {
                    toggle.Content    = name;
                    toggle.IsChecked  = false;
                    LanguageService.Load(code);
                    ApplyLanguage(code);
                    RefreshLangPackButtons();
                };
                popupPanel.Children.Add(itemBtn);
                if (string.Equals(code, LanguageService.CurrentCode, StringComparison.OrdinalIgnoreCase))
                    selectedIdx = i;
                i++;
            }

            toggle.Content = packs.Count > 0 ? packs[selectedIdx].Name : "English";

            LangPacksPanel.Children.Add(toggle);
            LangPacksPanel.Children.Add(popup); // the Popup takes no visible space in the WrapPanel — it renders on a separate layer
        }

