        private void ApplyLanguage(string lang)
        {
            bool ro = lang == "ro";

            // Tr(): resolve string for current language
            // For en/ro: direct. For others: look up LanguageService "UI" section using en as key.
            string Tr(string en, string r)
            {
                if (lang == "ro") return r;
                if (lang != "en")
                {
                    // Use the English string as lookup key (spaces->underscores, lowercase)
                    var key = System.Text.RegularExpressions.Regex.Replace(
                        en.Replace("&","").ToLowerInvariant(), @"[^a-z0-9]+", "_").Trim('_');
                    // The full key first (that is how the long keys are written in de/fr.json), then the variant cut at 60 characters.
                    var translated = LanguageService.S("UI", key, "");
                    if (string.IsNullOrEmpty(translated) && key.Length > 60)
                        translated = LanguageService.S("UI", key[..60], "");
                    if (!string.IsNullOrEmpty(translated)) return translated;
                    // the same text may be translated as a fixed page text (the PageText section)
                    if (LiteralTexts.HasTranslation(en)) return LiteralTexts.Translate(en);
                }
                return en;
            }

            void T(TextBlock? tb, string en, string r) { if (tb != null) tb.Text = Tr(en, r); }
            void Tip(FrameworkElement? e, string en, string r) { if (e != null) e.ToolTip = Tr(en, r); }
            Tip(FindName("BorderDashHardwareCard")  as FrameworkElement, "Click for details", "Click pentru detalii");
