            // Icon-aware button helper: builds StackPanel with Viewbox+Path + TextBlock
            void IconB(Button? b, string en, string r)
            {
                if (b == null) return;
                var text = Tr(en, r);
                string? pathData = null;
                if (b.Name != null && _btnIcons.TryGetValue(b.Name, out var pd))
                    pathData = pd;
                
                if (pathData != null)
                {
                    var sp = new StackPanel { Orientation = System.Windows.Controls.Orientation.Horizontal };
                    sp.VerticalAlignment = VerticalAlignment.Center;
                    
                    var vb = new System.Windows.Controls.Viewbox { Width = 13, Height = 13 };
                    vb.Effect = null;
                    vb.Margin = new Thickness(0, 0, 5, 0);
                    var cvs = new System.Windows.Controls.Canvas { Width = 24, Height = 24 };
                    var path = new WpfPath();
                    path.Data = SMDWin.Services.FluentIcons.Get(pathData);
                    bool coloredBg = b.Style == TryFindResource("DangerButtonStyle") as Style
                                   || b.Style == TryFindResource("PrimaryButtonStyle") as Style
                                   || (b is Wpf.Ui.Controls.Button uiBtnIconB
                                       && uiBtnIconB.Appearance is Wpf.Ui.Controls.ControlAppearance.Danger
                                                                   or Wpf.Ui.Controls.ControlAppearance.Primary
                                                                   or Wpf.Ui.Controls.ControlAppearance.Success
                                                                   or Wpf.Ui.Controls.ControlAppearance.Caution);
                    // the icon follows the button's text colour (the inherited TextElement.Foreground), not a colour fixed at construction —
                    // it stays visible on Primary ↔ Secondary and on a theme change.
                    _ = coloredBg;
                    path.SetBinding(System.Windows.Shapes.Shape.FillProperty, new System.Windows.Data.Binding
                    {
                        Path = new PropertyPath(System.Windows.Documents.TextElement.ForegroundProperty),
                        RelativeSource = new System.Windows.Data.RelativeSource(System.Windows.Data.RelativeSourceMode.Self),
                    });
                    cvs.Children.Add(path);
                    vb.Child = cvs;
                    sp.Children.Add(vb);
                    
                    sp.Children.Add(new TextBlock { Text = text, VerticalAlignment = VerticalAlignment.Center });
                    b.Content = sp;
                }
                else
                {
                    b.Content = text;
                }
            }

